from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up all devices.
prime_hub = PrimeHub()
motor = Motor(Port.A, Direction.COUNTERCLOCKWISE)
motor_2 = Motor(Port.B, Direction.CLOCKWISE)
drive_base = DriveBase(motor, motor_2, 56, 114)


# The main program starts here.
drive_base.straight(560)
drive_base.settings(turn_rate=40)
drive_base.turn(-90)
drive_base.settings(straight_speed=65)
drive_base.straight(200)
drive_base.straight(-100)
drive_base.turn(-75)
drive_base.settings(straight_speed=900)
drive_base.straight(800)
raise SystemExit
